// Extension store (/store/): category switcher, search and snippet previews.
// The pages are generated by scripts/build-store.mjs; this only adds behavior.
import { Spring } from "./motion.js";

const toolbar = document.querySelector<HTMLElement>("[data-store-toolbar]");
const search = document.querySelector<HTMLInputElement>("[data-store-search]");
const segments = document.querySelector<HTMLElement>("[data-segments]");
const thumb = document.querySelector<HTMLElement>("[data-segments-thumb]");
const segmentButtons = Array.from(document.querySelectorAll<HTMLButtonElement>("[data-segment]"));
const shelves = Array.from(document.querySelectorAll<HTMLElement>("[data-store-shelf]"));
const emptyMessage = document.querySelector<HTMLElement>("[data-store-empty]");

let category = "all";

function applyFilter(): void {
  const tokens = (search?.value ?? "").toLocaleLowerCase().split(/\s+/).filter(Boolean);
  let shown = 0;
  for (const shelf of shelves) {
    let shelfShown = 0;
    const inCategory = category === "all" || shelf.dataset.storeShelf === category;
    for (const card of Array.from(shelf.querySelectorAll<HTMLElement>("[data-store-card]"))) {
      const haystack = card.dataset.search ?? "";
      const match = inCategory && tokens.every((token) => haystack.includes(token));
      card.hidden = !match;
      if (match) shelfShown += 1;
    }
    shelf.hidden = shelfShown === 0;
    shown += shelfShown;
  }
  if (emptyMessage) emptyMessage.hidden = shown > 0;
}

// The selection thumb slides between segments on two independent springs
// (position and width), so a quick second tap redirects it mid-flight.
const thumbX = new Spring(0, (x) => thumb?.style.setProperty("--x", `${x}px`));
const thumbWidth = new Spring(0, (width) => thumb?.style.setProperty("--w", `${width}px`));

function moveThumb(button: HTMLButtonElement, animate: boolean): void {
  if (!thumb) return;
  if (animate) {
    thumbX.to(button.offsetLeft, { damping: 1, response: 0.35 });
    thumbWidth.to(button.offsetWidth, { damping: 1, response: 0.35 });
  } else {
    thumbX.set(button.offsetLeft);
    thumbWidth.set(button.offsetWidth);
  }
}

function selectSegment(button: HTMLButtonElement, focus = false): void {
  category = button.dataset.segment ?? "all";
  for (const other of segmentButtons) {
    const selected = other === button;
    other.setAttribute("aria-checked", String(selected));
    other.tabIndex = selected ? 0 : -1;
  }
  moveThumb(button, true);
  if (focus) button.focus();
  // Keep the chosen segment in view when the switcher scrolls on small screens.
  if (segments && segments.scrollWidth > segments.clientWidth) {
    segments.scrollTo({ left: button.offsetLeft - segments.clientWidth / 2 + button.offsetWidth / 2, behavior: "smooth" });
  }
  applyFilter();
}

if (segments && segmentButtons.length) {
  segments.classList.add("is-ready");
  segmentButtons.forEach((button, index) => {
    button.tabIndex = index === 0 ? 0 : -1;
    // Respond on press, not on release.
    button.addEventListener("pointerdown", (event) => {
      if (event.button === 0) selectSegment(button);
    });
    button.addEventListener("click", () => selectSegment(button));
  });
  segments.addEventListener("keydown", (event) => {
    const current = segmentButtons.findIndex((button) => button.getAttribute("aria-checked") === "true");
    const step = { ArrowRight: 1, ArrowDown: 1, ArrowLeft: -1, ArrowUp: -1 }[event.key];
    if (step === undefined) return;
    event.preventDefault();
    selectSegment(segmentButtons[(current + step + segmentButtons.length) % segmentButtons.length], true);
  });
  const initial = segmentButtons[0];
  moveThumb(initial, false);
  // Fonts and layout can settle after load; re-measure without animating.
  window.addEventListener("resize", () => {
    const selected = segmentButtons.find((button) => button.getAttribute("aria-checked") === "true");
    if (selected) moveThumb(selected, false);
  });
  void document.fonts?.ready.then(() => moveThumb(initial, false));
}

search?.addEventListener("input", applyFilter);
search?.addEventListener("keydown", (event) => {
  if (event.key === "Escape" && search.value) {
    search.value = "";
    applyFilter();
  }
});

// The toolbar is a floating material: its edge shows only once it is stuck
// over content.
if (toolbar) {
  const update = (): void => {
    const headerBottom = document.querySelector(".site-header")?.getBoundingClientRect().bottom ?? 66;
    toolbar.classList.toggle("is-stuck", toolbar.getBoundingClientRect().top <= headerBottom + 1);
  };
  window.addEventListener("scroll", () => requestAnimationFrame(update), { passive: true });
  update();
}

// Snippet previews on extension pages: tabs with arrow-key navigation.
for (const group of Array.from(document.querySelectorAll<HTMLElement>("[data-snippets]"))) {
  const tabs = Array.from(group.querySelectorAll<HTMLButtonElement>('[role="tab"]'));
  const panels = Array.from(group.querySelectorAll<HTMLElement>('[role="tabpanel"]'));
  group.classList.add("is-ready");
  const select = (index: number, focus = false): void => {
    tabs.forEach((tab, i) => {
      tab.setAttribute("aria-selected", String(i === index));
      tab.tabIndex = i === index ? 0 : -1;
    });
    panels.forEach((panel, i) => panel.toggleAttribute("data-inactive", i !== index));
    if (focus) tabs[index].focus();
  };
  tabs.forEach((tab, index) => {
    tab.addEventListener("pointerdown", (event) => {
      if (event.button === 0) select(index);
    });
    tab.addEventListener("click", () => select(index));
    tab.addEventListener("keydown", (event) => {
      const step = { ArrowDown: 1, ArrowRight: 1, ArrowUp: -1, ArrowLeft: -1 }[event.key];
      if (step === undefined) return;
      event.preventDefault();
      select((index + step + tabs.length) % tabs.length, true);
    });
  });
}

export {};
